CREATE TABLE `dues_out` (
  `id` int NOT NULL AUTO_INCREMENT,
  `army_number` varchar(50) NOT NULL,
  `rank` varchar(20) DEFAULT NULL,
  `trade` varchar(50) DEFAULT NULL,
  `name` varchar(100) DEFAULT NULL,
