INSERT INTO `roll_call_points` VALUES (4,'OR_REQUEST','Equipment Requirement','test','15717788X','2026-03-17 06:03:35','REJECTED',NULL),(5,'SM_SUGGESTION','Training Improvement','1. AV note book update karenge daily base par.Carry same note during CO sahab interview.\n2. Weekly same notebook check hogi, and trade releted test bhi hoga.\n3. Training day me all store men store and log book ready karenge aur eqpt ki functionality check karenge. faulty eqpt store me nahi hoga order by CO sahab.\n4. indl declaration form fill up karake coy office me deposit karayenge ( concern mobile/SIM ).\n5. Social media violation and CMP report accepted nahi hogi.\n6. leave ke during helmat ka use karenge and koi bhi over speed veh nahi drive karenga, nahi alcohal ka istmal karenga.\n7. line me koi bhi alcohal ka use nahi karenga.\n',NULL,'2026-03-20 13:15:06','SUGGESSTED',NULL),(7,'OR_REQUEST','Administrative Issue','Sir,\n   1.  Move detail 1 month pahale sign hona chahiye shriman.','15745698M','2026-03-20 14:38:58','REJECTED',NULL),(8,'OR_REQUEST','Administrative Issue','Sir,\n 1. Shriman library me english paper hona chahiye.','A4354275Y','2026-03-20 14:45:45','APPROVED',NULL),(9,'OR_REQUEST','Equipment','computer','15717788x','2026-03-27 03:47:09','APPROVED','sanstion'),(10,'OR_REQUEST','Medical','jai hind saab OR line mein medical Kit hona chaiye saab','15718811M','2026-03-31 08:07:40','APPROVED','Adjt pl discuss'),(11,'OR_REQUEST','Accommodation','QTR 1 SAAL KE BAAD 3 MONTH EXTENSION HONA CHAHIYE,  POSTING OUT TAK MILNA CHAHIYE .','15734014L','2026-04-11 03:36:35','REJECTED',NULL),(12,'OR_REQUEST','Admin','BHAROSA APP, ISMEIN KAISE PATA CHALE KE HUM SUBHA UTHA TE HI  KHUSH HAI YA DUKHI','A4206563Y','2026-04-11 03:43:13','REJECTED',NULL),(13,'OR_REQUEST','Admin','clothing timing fix hona chahiye','A4352898K','2026-04-13 06:12:54','REJECTED',NULL),(14,'SM_SUGGESTION','Discipline','1. Jawan aur JCOs ke beech mein manmutav nahi hona chayiye.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(15,'SM_SUGGESTION','Discipline','2. Sabhi Army Jawan fake news per dhan nahi dena chayiye.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(16,'SM_SUGGESTION','Discipline','3. Sabhi Jawan chutti se return aane ke badh counselling kare, taki apki ki parivarik samashya ke bare me Unit mein pata chale.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(17,'SM_SUGGESTION','Discipline','4. Sabhi Jawan leave tadha Unit mein Ghadi chalete samaye ISI marked Helmet aur seatbelt phene.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(18,'SM_SUGGESTION','Discipline','5. Leave ke dorain Ghadi chalete samay Liquor ke sevan na kare.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(19,'SM_SUGGESTION','Discipline','6. Gadi chalate samay mobile phone pe bat na kare.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(20,'SM_SUGGESTION','Discipline','7. Chutti ke duran apne parichaya patra (I-Card) ki suraksha har wakt niyam anusaar sunishit kare.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(21,'SM_SUGGESTION','Discipline','8. Koi bhi rajneetik party ki karyavahion mein hissa na kare.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL),(22,'SM_SUGGESTION','Discipline','9. Gaadi 50 Kmh speed se jayada nahi chalana.',NULL,'2026-09-01 06:48:07','SUGGESSTED',NULL);
